static int SumCsv(ReadOnlySpan<char> text)
{
    int total = 0;
    while (!text.IsEmpty)
    {
        int comma = text.IndexOf(',');
        ReadOnlySpan<char> part = comma < 0 ? text : text[..comma];
        total += int.Parse(part);
        if (comma < 0) break;
        text = text[(comma + 1)..];
    }
    return total;
}

Console.WriteLine(SumCsv("10,20,30"));

