static unsafe int Sum(int* values, int length)
{
    int total = 0;
    for (int i = 0; i < length; i++)
        total += values[i];
    return total;
}

int[] numbers = { 10, 20, 30 };
unsafe
{
    fixed (int* pointer = numbers)
    {
        Console.WriteLine(Sum(pointer, numbers.Length));
    }
}

